class TestDiagnosticRuleImportBoundary:
    """Iteration 33A: keep the extracted runtime import boundary safe."""

    @staticmethod
    def _run_fresh_python(code: str) -> None:
        result = subprocess.run(
            [sys.executable, "-c", code],
            cwd=os.path.dirname(os.path.abspath(__file__)),
            env={**os.environ, "PYTHONDONTWRITEBYTECODE": "1"},
            capture_output=True,
            text=True,
            check=False,
        )
        assert result.returncode == 0, result.stderr

    def test_diagnostic_rules_first_import_is_safe(self):
        self._run_fresh_python(
            "import sys; import diagnostic_rules; "
            "assert 'syscheck' not in sys.modules; import syscheck; "
            "assert syscheck.build_default_rule_engine()._registry.rules"
        )

    def test_syscheck_first_import_is_safe(self):
        self._run_fresh_python(
            "import syscheck; import diagnostic_rules; "
            "assert syscheck.build_default_rule_engine()._registry.rules"
        )

    def test_all_rule_runtime_reexports_are_identical(self):
        import diagnostic_rules
        import syscheck

        names = (
            "DiagnosticRuleResult",
            "DiagnosticEvaluation",
            "DiagnosticRuleError",
            "UnsupportedObservationRuleError",
            "AmbiguousObservationRuleError",
            "DuplicateDiagnosticRuleError",
            "DuplicateFindingError",
            "DuplicateEvidenceError",
            "DiagnosticRule",
            "BtrfsDeviceErrorRule",
            "BtrfsScrubStatusRule",
            "WirePlumberSegfaultRule",
            "GeneralSegfaultRule",
            "MinorSegfaultRule",
            "KernelTaintRule",
            "KernelOomRule",
            "GpuI915HangRule",
            "AmdgpuResetFailRule",
            "GpuNvidiaXid79Rule",
            "PcieAerErrorRule",
            "NvmeControllerReliabilityRule",
            "HardwareMceEdacRule",
            "FilesystemIoErrorRule",
            "HardwareThermalThrottlingRule",
            "KernelOopsPanicRule",
            "KernelSoftLockupRule",
            "KernelHardLockupRule",
            "KernelHungTaskRule",
            "KernelRcuStallRule",
            "PlatformAcpiFirmwareErrorRule",
            "KernelFirmwareLoadFailRule",
            "UsbEnumerationFailRule",
            "IommuFaultRule",
            "FailedSystemUnitRule",
            "FailedUserUnitRule",
            "KernelCountRule",
            "BootDelayRule",
            "StorageUsageRule",
            "DiagnosticRuleRegistry",
            "DiagnosticRuleEngine",
            "build_default_rule_engine",
        )

        assert all(
            getattr(syscheck, name) is getattr(diagnostic_rules, name) for name in names
        )


# ═══════════════════════════════════════════════════════════════════
# Test 1: Filtrowanie własnych wpisów z dziennika
# ═══════════════════════════════════════════════════════════════════


class TestFilterOwnJournalEntries:
    """T1: Duplicate journal entries generated by syscheck.py."""

    def test_filter_removes_syscheck_py_entries(self):
        text = (
            "lip 27 08:09:51 <REDACTED-HOST> kernel: wireplumber[1274]: segfault at 0 ip ... in libspa-libcamera.so\n"
            "lip 27 08:09:52 <REDACTED-HOST> kernel: wireplumber[1387]: segfault at 0 ip ... in libspa-libcamera.so\n"
            "lip 27 10:28:22 <REDACTED-HOST> syscheck.py[97929]: lip 27 08:09:51 <REDACTED-HOST> kernel: wireplumber[1274]: segfault at 0\n"
            "lip 27 10:28:22 <REDACTED-HOST> syscheck.py[97929]: ### Segfaulty z bie\u017c\u0105cego bootu\n"
            "lip 27 10:35:00 <REDACTED-HOST> syscheck.py[102256]: bash -c journalctl -b"
        )
        result = _filter_own_journal_entries(text)
        assert "syscheck.py" not in result
        assert "kernel: wireplumber[1274]" in result
        assert "kernel: wireplumber[1387]" in result
        assert "Segfaulty" not in result
        assert "bash -c journalctl" not in result

    def test_filter_preserves_original_kernel_lines(self):
        text = (
            "lip 27 08:09:51 <REDACTED-HOST> kernel: wireplumber[1274]: segfault at 0\n"
            "lip 27 10:28:22 <REDACTED-HOST> syscheck.py[97929]: lip 27 08:09:51 <REDACTED-HOST> kernel: wireplumber[1274]: segfault at 0"
        )
        result = _filter_own_journal_entries(text)
        lines = [ln for ln in result.split("\n") if ln.strip()]
        assert len(lines) == 1
        assert "kernel:" in lines[0]
        assert "syscheck.py" not in lines[0]


# ═══════════════════════════════════════════════════════════════════
# Test 2: Deduplikacja linii dziennika
# ═══════════════════════════════════════════════════════════════════


class TestDeduplicateJournalLines:
    """Deduplikacja po tre\u015bci (ignoruj\u0105c timestamp)."""

    def test_dedup_removes_identical_messages(self):
        text = (
            "lip 27 08:09:51 <REDACTED-HOST> kernel: error: something bad\n"
            "lip 27 08:09:52 <REDACTED-HOST> kernel: error: something bad\n"
            "lip 27 08:09:53 <REDACTED-HOST> kernel: BTRFS error: failed to open device"
        )
        result = _deduplicate_journal_lines(text)
        lines = [ln for ln in result.split("\n") if ln.strip()]
        assert len(lines) == 2  # 2 unikalne komunikaty
        assert "BTRFS" in result
        assert result.count("something bad") == 1

    def test_dedup_preserves_unique_lines(self):
        text = (
            "lip 27 08:09:51 <REDACTED-HOST> kernel: line one\n"
            "lip 27 08:09:52 <REDACTED-HOST> kernel: line two\n"
            "lip 27 08:09:53 <REDACTED-HOST> kernel: line three"
        )
        result = _deduplicate_journal_lines(text)
        lines = [ln for ln in result.split("\n") if ln.strip()]
        assert len(lines) == 3


# ═══════════════════════════════════════════════════════════════════
# Test 3: Poprawne zliczanie segfault\u00f3w — 5 realnych, nie 22
# ═══════════════════════════════════════════════════════════════════


class TestCountUniqueSegfaults:
    """T2: Five real WirePlumber crashes not reported as 22."""

    def test_five_real_segfaults_counted_as_five(self):
        # 5 unikalnych segfault\u00f3w wireplumber z r\u00f3\u017cnymi adresami hex,
        # + 5 kopii z syscheck.py + nag\u0142\u00f3wki = ~22 linii z "segfault"
        text = "\n".join(
            [
                "lip 27 08:09:51 <REDACTED-HOST> kernel: wireplumber[1274]: segfault at 0 ip 00007f2c9743a55c error 4 in libspa-libcamera.so[13155c,7f2c97382000+f0000]",
                "lip 27 08:09:52 <REDACTED-HOST> kernel: wireplumber[1387]: segfault at 0 ip 00007f3f5ce6055c error 4 in libspa-libcamera.so[13155c,7f3f5cda8000+f0000]",
                "lip 27 08:09:52 <REDACTED-HOST> kernel: wireplumber[1407]: segfault at 0 ip 00007f470be6055c error 4 in libspa-libcamera.so[13155c,7f470bda8000+f0000]",
                "lip 27 08:09:53 <REDACTED-HOST> kernel: wireplumber[1427]: segfault at 0 ip 00007f488b43055c error 4 in libspa-libcamera.so[13155c,7f488b378000+f0000]",
                "lip 27 08:09:53 <REDACTED-HOST> kernel: wireplumber[1445]: segfault at 0 ip 00007f5f61d5955c error 4 in libspa-libcamera.so[13155c,7f5f61ca1000+f0000]",
                # Kopie z syscheck.py
                "lip 27 10:28:22 <REDACTED-HOST> syscheck.py[97929]: lip 27 08:09:51 <REDACTED-HOST> kernel: wireplumber[1274]: segfault at 0",
                "lip 27 10:28:22 <REDACTED-HOST> syscheck.py[97929]: lip 27 08:09:52 <REDACTED-HOST> kernel: wireplumber[1387]: segfault at 0",
                "lip 27 10:28:22 <REDACTED-HOST> syscheck.py[97929]: lip 27 08:09:52 <REDACTED-HOST> kernel: wireplumber[1407]: segfault at 0",
                "lip 27 10:28:22 <REDACTED-HOST> syscheck.py[97929]: lip 27 08:09:53 <REDACTED-HOST> kernel: wireplumber[1427]: segfault at 0",
                "lip 27 10:28:22 <REDACTED-HOST> syscheck.py[97929]: lip 27 08:09:53 <REDACTED-HOST> kernel: wireplumber[1445]: segfault at 0",
                # Nag\u0142\u00f3wki i \u015bmieci
                "lip 27 10:28:22 <REDACTED-HOST> syscheck.py[97929]: ### Segfaulty z bie\u017c\u0105cego bootu",
                "lip 27 10:28:22 <REDACTED-HOST> syscheck.py[97929]: **F1.** Wielokrotne segfaulty podczas bootu (22)",
                "lip 27 10:28:22 <REDACTED-HOST> syscheck.py[97929]: bash -c journalctl -b | grep -i segfault",
                # Jeszcze jedna kopia
                "lip 27 10:28:22 <REDACTED-HOST> syscheck.py[97929]: lip 27 08:09:51 <REDACTED-HOST> kernel: wireplumber[1274]: segfault at 0 ip ... in libspa-libcamera.so",
                "lip 27 10:28:22 <REDACTED-HOST> syscheck.py[97929]: lip 27 08:09:52 <REDACTED-HOST> kernel: wireplumber[1387]: segfault at 0 ip ... in libspa-libcamera.so",
                "lip 27 10:28:22 <REDACTED-HOST> syscheck.py[97929]: lip 27 08:09:52 <REDACTED-HOST> kernel: wireplumber[1407]: segfault at 0 ip ... in libspa-libcamera.so",
            ]
        )
        count = _count_unique_segfaults(text)
        assert count == 5, f"Expected 5 unique segfaults, got {count}"

    def test_no_segfaults_returns_zero(self):
        text = "lip 27 08:09:51 <REDACTED-HOST> kernel: INFO: system started"
        count = _count_unique_segfaults(text)
        assert count == 0

    def test_single_segfault_counted_once(self):
        text = "\n".join(
            [
                "lip 27 08:09:51 <REDACTED-HOST> kernel: python[1234]: segfault at 0 ip 00007f in libpython.so[1000,7f010000]",
                "lip 27 10:28:22 <REDACTED-HOST> syscheck.py[97929]: lip 27 08:09:51 <REDACTED-HOST> kernel: python[1234]: segfault at 0",
            ]
        )
        count = _count_unique_segfaults(text)
        assert count == 1


# ═══════════════════════════════════════════════════════════════════
# Test 4: Obs\u0142uga pacman -Qdt rc=1
# ═══════════════════════════════════════════════════════════════════


class TestPacmanReturnCodes:
    """T3: pacman -Qdt returning 1 with empty output."""

    def test_pacman_qdt_rc1_empty_is_empty_ok(self):
        result = CmdResult(
            command="pacman -Qdt",
            stdout="",
            stderr="",
            return_code=1,
            execution_status="empty_ok",
        )
        assert result.execution_status == "empty_ok"
        assert result.return_code == 1
        assert not result.stdout

    def test_pacman_qdt_rc1_with_stderr_is_error(self):
        result = CmdResult(
            command="pacman -Qdt",
            stdout="",
            stderr="error: database not found",
            return_code=1,
            execution_status="error",
        )
        assert result.execution_status == "error"

    def test_pacman_qdt_rc0_with_output_is_ok(self):
        result = CmdResult(
            command="pacman -Qdt",
            stdout="orphan-package 1.0-1",
            stderr="",
            return_code=0,
            execution_status="ok",
        )
        assert result.execution_status == "ok"
        assert result.stdout == "orphan-package 1.0-1"


# ═══════════════════════════════════════════════════════════════════
# Test 5: Zliczanie kernel — bez headers i firmware
# ═══════════════════════════════════════════════════════════════════


class TestKernelCounting:
    """T4: Kernel package counting excluding headers and firmware."""

    def test_excludes_headers_and_firmware(self):
        pkg_list = """linux 7.1.5.arch1-1
linux-api-headers 7.1-1
linux-cachyos 7.1.4-1
linux-cachyos-headers 7.1.4-1
linux-cachyos-lts 6.18.38-2
linux-cachyos-lts-headers 6.18.38-2
linux-firmware 20260622-1
linux-firmware-amdgpu 20260622-1
linux-lts 6.18.40-2
linux-lts-headers 6.18.40-2"""
        bootable_count, total_count, bootable_list = _count_kernel_packages(pkg_list)
        # Should be: linux, linux-cachyos, linux-cachyos-lts, linux-lts = 4
        assert bootable_count == 4, f"Expected 4 bootable kernels, got {bootable_count}"
        assert total_count == 10  # 4 kernels + 6 non-bootable
        assert "linux 7.1.5.arch1-1" in bootable_list
        assert "linux-lts-headers" not in str(bootable_list)

    def test_empty_list(self):
        bootable_count, _, _ = _count_kernel_packages("")
        assert bootable_count == 0

    def test_only_headers(self):
        pkg_list = """linux-headers 7.1.5-1
linux-api-headers 7.1-1
linux-firmware 20260622-1"""
        bootable_count, _, _ = _count_kernel_packages(pkg_list)
        assert bootable_count == 0

    def test_kernel_with_tools_not_counted_as_kernel(self):
        pkg_list = """linux 7.1.5-1
linux-tools 7.1.5-1
linux-utils 1.0-1"""
        bootable_count, _, _ = _count_kernel_packages(pkg_list)
        assert bootable_count > 0  # At minimum, linux is counted

    def test_debian_dpkg_output_counts_installed_kernel_images(self):
        pkg_list = """Desired=Unknown/Install/Remove/Purge/Hold
| Status=Not/Inst/Conf-files/Unpacked/halF-conf/Half-inst/trig-aWait/Trig-pend
|/ Err?=(none)/Reinst-required (Status,Err: uppercase=bad)
||/ Name                                Version               Architecture Description
+++-===================================-=====================-============-=================================
ii  linux-image-6.8.0-31-generic        6.8.0-31.31          amd64        Signed kernel image generic
ii  linux-image-6.8.0-32-generic        6.8.0-32.32          amd64        Signed kernel image generic
ii  linux-headers-6.8.0-32              6.8.0-32.32          all          Header files
ii  linux-firmware                      20240318.git3b128b60-0ubuntu2 all Firmware
rc  linux-image-6.8.0-30-generic        6.8.0-30.30          amd64        Removed kernel image
"""
        bootable_count, total_count, bootable_list = _count_kernel_packages(pkg_list)

        assert bootable_count == 2
        assert total_count == 4
        assert bootable_list == [
            "linux-image-6.8.0-31-generic 6.8.0-31.31",
            "linux-image-6.8.0-32-generic 6.8.0-32.32",
        ]

    def test_rpm_output_counts_distinct_kernel_versions(self):
        pkg_list = """kernel-6.8.9-200.fc40.x86_64
kernel-core-6.8.9-200.fc40.x86_64
kernel-modules-6.8.9-200.fc40.x86_64
kernel-devel-6.8.9-200.fc40.x86_64
kernel-headers-6.8.9-200.fc40.x86_64
kernel-core-6.8.10-200.fc40.x86_64
kernel-modules-6.8.10-200.fc40.x86_64"""
        bootable_count, total_count, bootable_list = _count_kernel_packages(pkg_list)

        assert bootable_count == 2
        assert total_count == 7
        assert bootable_list == [
            "kernel-core-6.8.9-200.fc40.x86_64",
            "kernel-core-6.8.10-200.fc40.x86_64",
        ]


# ═══════════════════════════════════════════════════════════════════
# Test 6: Failed systemd units
# ═══════════════════════════════════════════════════════════════════


class TestSystemdFailedUnits:
    """T5: Failed system timer appearing in final findings."""

    def test_has_failed_units_logrotate_timer(self):
        output = """  UNIT            LOAD   ACTIVE SUB    DESCRIPTION
\u25cf logrotate.timer loaded failed failed Daily rotation of log files

Legend: LOAD   \u2192 Reflects whether the unit definition was properly loaded.

1 loaded units listed."""
        assert SysCheckEngine._has_failed_units(output) is True

    def test_has_failed_units_no_failures(self):
        output = """  UNIT LOAD ACTIVE SUB DESCRIPTION
0 loaded units listed."""
        assert SysCheckEngine._has_failed_units(output) is False

    def test_has_failed_units_empty(self):
        assert SysCheckEngine._has_failed_units("") is False

    def test_extract_failed_unit_names_timer(self):
        output = (
            "  UNIT            LOAD   ACTIVE SUB    DESCRIPTION\n"
            "\u25cf logrotate.timer loaded failed failed Daily rotation of log files"
        )
        units = SysCheckEngine._extract_failed_unit_names(output)
        assert "logrotate.timer" in units
        assert len(units) == 1

    # T6: Failed user service appearing in findings
    def test_extract_failed_unit_names_user_service(self):
        output = (
            "  UNIT                 LOAD   ACTIVE SUB    DESCRIPTION\n"
            "\u25cf niri-session.service loaded failed failed Niri Session Restore"
        )
        units = SysCheckEngine._extract_failed_unit_names(output)
        assert "niri-session.service" in units

    def test_extract_failed_unit_names_multiple(self):
        output = (
            "  UNIT            LOAD   ACTIVE SUB    DESCRIPTION\n"
            "\u25cf logrotate.timer loaded failed failed Daily rotation of log files\n"
            "\u25cf niri-session.service loaded failed failed Niri Session Restore"
        )
        units = SysCheckEngine._extract_failed_unit_names(output)
        assert len(units) == 2
        assert "logrotate.timer" in units
        assert "niri-session.service" in units


# ═══════════════════════════════════════════════════════════════════
# Test 7: Missing nvme executable
# ═══════════════════════════════════════════════════════════════════


class TestMissingOptionalDependency:
    """T7: Missing nvme executable classified as optional dependency missing."""

    def test_nvme_not_found_is_optional_dependency(self):
        result = CmdResult(
            command="nvme list",
            stdout="",
            stderr="Polecenie nie znalezione: nvme",
            return_code=-1,
            execution_status="not_found",
            optional_dependency=True,
        )
        assert result.execution_status == "not_found"
        assert result.optional_dependency is True
        assert result.to_fallback_text() == "(nie znaleziono: nvme list)"

    def test_nft_not_found_is_optional_dependency(self):
        result = CmdResult(
            command="nft list ruleset",
            stdout="",
            stderr="",
            return_code=-1,
            execution_status="not_found",
            optional_dependency=True,
        )
        assert result.optional_dependency is True
        assert result.execution_status == "not_found"

    def test_required_command_not_found(self):
        result = CmdResult(
            command="lsblk",
            stdout="",
            stderr="",
            return_code=-1,
            execution_status="not_found",
            optional_dependency=False,
        )
        assert result.execution_status == "not_found"
        assert result.optional_dependency is False


# ═══════════════════════════════════════════════════════════════════
# Test 8: Btrfs permission failure
# ═══════════════════════════════════════════════════════════════════


class TestBtrfsClassification:
    """T8: Btrfs permission failure not classified as corruption."""

    def test_permission_denied_classified_correctly(self):
        result = CmdResult(
            command="btrfs scrub status /",
            stdout="",
            stderr="ERROR: cannot check scrub status: Operation not permitted",
            return_code=1,
            execution_status="error",
            privilege_required=True,
        )
        status = _classify_btrfs_status(result)
        assert status == "permission_denied", (
            f"Expected 'permission_denied', got '{status}'"
        )

    def test_no_scrub_classified_correctly(self):
        result = CmdResult(
            command="btrfs scrub status /",
            stdout="no scrub data for /",
            stderr="",
            return_code=0,
            execution_status="ok",
        )
        status = _classify_btrfs_status(result)
        assert status == "no_scrub", f"Expected 'no_scrub', got '{status}'"

    def test_ok_scrub(self):
        result = CmdResult(
            command="btrfs scrub status /",
            stdout="scrub status for ...",
            stderr="",
            return_code=0,
            execution_status="ok",
        )
        status = _classify_btrfs_status(result)
        assert status == "ok"

    def test_command_not_found(self):
        result = CmdResult(
            command="btrfs filesystem show /",
            stdout="",
            stderr="Polecenie nie znalezione: btrfs",
            return_code=-1,
            execution_status="not_found",
        )
        status = _classify_btrfs_status(result)
        assert status == "command_not_found"

    def test_device_missing_in_output(self):
        result = CmdResult(
            command="btrfs filesystem show /",
            stdout="devid 1 size 0 used 0 path /dev/nvme0n1p5 MISSING",
            stderr="",
            return_code=0,
            execution_status="ok",
        )
        status = _classify_btrfs_status(result)
        assert status == "device_missing", f"Expected 'device_missing', got '{status}'"


# ═══════════════════════════════════════════════════════════════════
# Test 9: Invalid temperature sensors
# ═══════════════════════════════════════════════════════════════════


class TestInvalidTemperatures:
    """T9: Invalid -273.3\u00b0C sensor ignored."""

    def test_absolute_zero_filtered_out(self):
        text = """acpitz-acpi-0
Adapter: ACPI interface
temp1:       -273.3\u00b0C
temp2:        +27.8\u00b0C

coretemp-isa-0000
Package id 0:  +52.0\u00b0C"""
        result = _filter_invalid_temperatures(text)
        assert "-273.3" not in result
        assert "+27.8" in result
        assert "+52.0" in result

    def test_normal_temperatures_preserved(self):
        text = """coretemp-isa-0000
Package id 0:  +52.0\u00b0C  (high = +100.0\u00b0C)
Core 0:        +42.0\u00b0C"""
        result = _filter_invalid_temperatures(text)
        assert "+52.0" in result
        assert "+42.0" in result
        assert "coretemp" in result

    def test_all_invalid_sensors_filtered(self):
        text = """sensor1: -273.2\u00b0C
sensor2: -273.1\u00b0C
sensor3: +25.0\u00b0C"""
        result = _filter_invalid_temperatures(text)
        assert "-273.2" not in result
        assert "-273.1" not in result
        assert "+25.0" in result

    def test_valid_negative_temperature_preserved(self):
        text = "temp1: -50.0\u00b0C"
        result = _filter_invalid_temperatures(text)
        assert "-50.0" in result


