# Test 10: Boot analysis — fstrim outside critical chain
# ═══════════════════════════════════════════════════════════════════


class TestBootAnalysis:
    """T10: fstrim.service outside critical boot chain not a boot slowdown."""

    def test_fstrim_not_in_critical_chain(self):
        blame = """41.891s fstrim.service
8.708s man-db.service
5.553s graphical.target"""

        critical_chain = """graphical.target @5.553s
\u2514\u2500multi-user.target @5.553s
  \u2514\u2500libvirtd.service @5.055s"""

        assert "fstrim.service" in blame
        assert "fstrim" not in critical_chain

    def test_graphical_target_reached_quickly(self):
        analyze = (
            "Startup finished in 14.425s (firmware) + 8.130s (loader) + "
            "2.906s (kernel) + 5.034s (initrd) + 5.553s (userspace) = 36.051s\n"
            "graphical.target reached after 5.553s in userspace."
        )
        # Verify format: "= X.Ys" for total time
        time_match = re.search(r"=\s*([\d.]+)s", analyze)
        assert time_match is not None
        assert float(time_match.group(1)) == 36.051
        # Verify that graphical.target was reached quickly
        graph_match = re.search(r"graphical\.target reached after ([\d.]+)s", analyze)
        assert graph_match is not None
        assert float(graph_match.group(1)) <= 10.0

    def test_fstrim_not_on_critical_path(self):
        blame_line = "41.891s fstrim.service"
        assert "fstrim" in blame_line


# ═══════════════════════════════════════════════════════════════════
# Test 11: Local vs external sockets
# ═══════════════════════════════════════════════════════════════════


class TestSocketClassification:
    """T11: Local-only and externally listening sockets distinguished."""

    def test_localhost_only_sockets(self):
        ss_output = """LISTEN 0 4096 127.0.0.1:11434 0.0.0.0:*
LISTEN 0 10   127.0.0.1:44097 0.0.0.0:*
LISTEN 0 128  127.0.0.1:11987 0.0.0.0:*
LISTEN 0 4096 [::1]:11987     [::]:*"""
        external, local = self._classify_sockets(ss_output)
        assert len(local) > 0

    def test_externally_listening_sockets(self):
        ss_output = """LISTEN 0 4096 0.0.0.0:8080 0.0.0.0:* users:(("myapp",pid=1234))
LISTEN 0 128  0.0.0.0:22   0.0.0.0:*"""
        external, _ = self._classify_sockets(ss_output)
        assert len(external) > 0

    def test_cups_is_excluded_from_external(self):
        ss_output = "LISTEN 0 4096 0.0.0.0:631 0.0.0.0:*"
        external, _ = self._classify_sockets(ss_output)
        assert all(":631" not in e for e in external)

    @staticmethod
    def _classify_sockets(ss_output: str):
        external = []
        local = []
        for line in ss_output.split("\n"):
            if "LISTEN" in line:
                addr_match = re.search(r"(\S+):(\d+)", line)
                if addr_match:
                    addr = addr_match.group(1)
                    port = addr_match.group(2)
                    if addr in ("127.0.0.1", "::1", "127.0.0.53", "127.0.0.54"):
                        local.append(f"{addr}:{port}")
                    elif addr in ("0.0.0.0", "::"):
                        if port not in ("631", "5355"):
                            external.append(f"{addr}:{port}")
                    elif addr.startswith("192.168.") or addr.startswith("10."):
                        external.append(f"{addr}:{port}")
        return external, local


# ═══════════════════════════════════════════════════════════════════
# Test 12: Stable finding IDs and ordering
# ═══════════════════════════════════════════════════════════════════


class TestFindingIdsAndOrdering:
    """T12: Stable deterministic finding IDs and ordering."""

    def test_finding_ids_unique_and_deterministic(self):
        finding1 = Finding(
            finding_id="BTRFS-ERR-001",
            title="Btrfs errors",
            severity="P1",
            confidence="Certain",
        )
        finding2 = Finding(
            finding_id="KRNL-COUNT-001",
            title="Too many kernels",
            severity="P3",
            confidence="Certain",
        )
        assert finding1.finding_id == "BTRFS-ERR-001"
        assert finding2.finding_id == "KRNL-COUNT-001"
        assert finding1.finding_id != finding2.finding_id

    def test_findings_sorted_by_severity(self):
        findings = [
            Finding("F-003", "Info", severity="Info", confidence="Certain"),
            Finding("F-001", "Critical", severity="P0", confidence="Certain"),
            Finding("F-002", "High", severity="P1", confidence="Certain"),
            Finding("F-004", "Low", severity="P3", confidence="Certain"),
        ]
        findings.sort(key=lambda f: Finding._severity_order.get(f.severity, 99))
        severities = [f.severity for f in findings]
        assert severities == ["P0", "P1", "P3", "Info"]

    def test_severity_tag_format(self):
        assert severity_tag("P0") == "P0 \u2013 krytyczny"
        assert severity_tag("P1") == "P1 \u2013 wysoki"
        assert severity_tag("P2") == "P2 \u2013 \u015bredni"
        assert severity_tag("P3") == "P3 \u2013 niski"

    def test_confidence_tag_format(self):
        assert confidence_tag("Certain") == "[Certain]"
        assert confidence_tag("Likely") == "[Likely]"
        assert confidence_tag("Guessing") == "[Guessing]"


