class TestPipelineSeparation:
    """Regression tests: Stage separation RAW→OBS→INT."""

    def test_engine_has_three_stage_methods(self):
        """Verifies the engine exposes the three pipeline stages."""
        engine = SysCheckEngine(output_dir="/tmp/test_syscheck_pipeline")
        assert hasattr(engine, "_derive_observations")
        assert hasattr(engine, "_interpret")
        assert hasattr(engine, "run_all")

    def test_observations_list_initialized(self):
        """Verifies observations list exists before collection."""
        engine = SysCheckEngine(output_dir="/tmp/test_syscheck_pipeline")
        assert isinstance(engine.observations, list)
        assert len(engine.observations) == 0

    def test_derive_observations_from_raw_diagnostics(self):
        """Verifies _derive_observations creates Observation from RawDiagnostic."""
        engine = SysCheckEngine(output_dir="/tmp/test_syscheck_pipeline")
        engine.raw_diagnostics = [
            RawDiagnostic(
                source_id="SEGFAULT-WP-001",
                category="segfault",
                payload={"segfault_type": "wireplumber"},
            ),
            RawDiagnostic(
                source_id="KRNL-INFO-001", category="kernel_count", payload={"count": 4}
            ),
        ]
        engine._derive_observations()
        assert len(engine.observations) == 2
        obs_ids = {o.obs_id for o in engine.observations}
        assert "SEGFAULT-WP-001" in obs_ids
        assert "KRNL-INFO-001" in obs_ids

    def test_observation_categories_mapped_correctly(self):
        """Verifies raw diagnostics produce correctly categorized observations."""
        engine = SysCheckEngine(output_dir="/tmp/test_syscheck_pipeline")
        engine.raw_diagnostics = [
            RawDiagnostic(
                source_id="BTRFS-SCRUB-001",
                category="btrfs_scrub",
                payload={"scrub_status": "no_scrub"},
            ),
            RawDiagnostic(
                source_id="SEGFAULT-WP-001",
                category="segfault",
                payload={"segfault_type": "wireplumber"},
            ),
            RawDiagnostic(
                source_id="KRNL-INFO-001", category="kernel_count", payload={"count": 4}
            ),
        ]
        engine._derive_observations()
        obs_by_id = {o.obs_id: o for o in engine.observations}
        assert obs_by_id["BTRFS-SCRUB-001"].category == "btrfs_scrub"
        assert obs_by_id["SEGFAULT-WP-001"].category == "segfault"
        assert obs_by_id["KRNL-INFO-001"].category == "kernel_count"

    def test_derive_observations_deterministic(self):
        """Identical RAW always produces identical observations."""
        raw_list = [
            RawDiagnostic(
                source_id="SEGFAULT-WP-001",
                category="segfault",
                payload={"segfault_type": "wireplumber"},
            ),
            RawDiagnostic(
                source_id="BTRFS-SCRUB-001",
                category="btrfs_scrub",
                payload={"scrub_status": "no_scrub"},
            ),
        ]
        engine1 = SysCheckEngine(output_dir="/tmp/t1")
        engine1.raw_diagnostics = raw_list
        engine1._derive_observations()
        engine2 = SysCheckEngine(output_dir="/tmp/t2")
        engine2.raw_diagnostics = raw_list
        engine2._derive_observations()
        cats1 = sorted(o.category for o in engine1.observations)
        cats2 = sorted(o.category for o in engine2.observations)
        assert cats1 == cats2

    def test_interpret_generates_findings_from_observations(self):
        """_interpret delegates to rule engine and generates findings."""
        engine = SysCheckEngine(output_dir="/tmp/test_syscheck_pipeline")
        engine.observations = [
            Observation(
                obs_id="KRNL-INFO-001", category="kernel_count", details={"count": 4}
            ),
            Observation(
                obs_id="SEGFAULT-WP-001",
                category="segfault",
                details={"segfault_type": "wireplumber"},
            ),
        ]
        engine._interpret()
        f_ids = {f.finding_id for f in engine.findings}
        assert "KRNL-INFO-001" in f_ids
        assert "SEGFAULT-WP-001" in f_ids
        assert len(engine.findings) >= 2

    def test_finding_sort_order_preserved(self):
        """Findings are sorted by severity (rule engine output + sort)."""
        # Test sorting contract directly - rule engine produces findings,
        # _interpret() sorts them.
        findings = [
            Finding(
                finding_id="F-P3",
                title="",
                severity="P3",
                confidence="Certain",
                domain=DiagnosticDomain.OTHER,
                kind=FindingKind.GENERAL,
            ),
            Finding(
                finding_id="F-P1",
                title="",
                severity="P1",
                confidence="Certain",
                domain=DiagnosticDomain.OTHER,
                kind=FindingKind.GENERAL,
            ),
            Finding(
                finding_id="F-Info",
                title="",
                severity="Info",
                confidence="Certain",
                domain=DiagnosticDomain.OTHER,
                kind=FindingKind.GENERAL,
            ),
            Finding(
                finding_id="F-P0",
                title="",
                severity="P0",
                confidence="Certain",
                domain=DiagnosticDomain.OTHER,
                kind=FindingKind.GENERAL,
            ),
        ]
        findings.sort(key=lambda f: Finding._severity_order.get(f.severity, 99))
        severities = [f.severity for f in findings]
        assert severities == ["P0", "P1", "P3", "Info"]


