class TestSchemaVersioning:
    """T2: schema version validation."""

    def test_serialized_json_contains_schema_version(self):
        snap = SystemSnapshot(
            metadata=SnapshotMetadata(hostname="h", kernel="k", syscheck_version="1.0"),
        )
        d = snap.to_dict()
        assert d["schema_version"] == SNAPSHOT_SCHEMA_VERSION

    def test_missing_schema_version_rejected(self):
        import pytest

        with pytest.raises(UnsupportedSnapshotSchemaError, match="Missing"):
            SystemSnapshot._from_validated({})

    def test_unsupported_schema_version_rejected(self):
        import pytest

        with pytest.raises(UnsupportedSnapshotSchemaError, match="Unsupported"):
            SystemSnapshot._from_validated({"schema_version": 999})

    def test_schema_version_invalid_type_rejected(self):
        import pytest

        with pytest.raises(UnsupportedSnapshotSchemaError, match="must be int"):
            SystemSnapshot._from_validated({"schema_version": "1"})

    def test_schema_version_2_roundtrip(self, tmp_path):
        snap = SystemSnapshot(
            metadata=SnapshotMetadata(hostname="h", kernel="k", syscheck_version="1.0"),
        )
        path = tmp_path / "snapshot.json"
        snap.to_json(path)
        loaded = SystemSnapshot.from_json(path)
        assert loaded.schema_version == 3
        assert loaded.metadata.hostname == "h"

    def test_schema_v1_migration_to_v3_works(self):
        """v1 snapshots are migrated to v2 with empty recommendations."""
        import json
        import tempfile
        import os

        v1_data = {
            "schema_version": 1,
            "metadata": {"hostname": "h", "kernel": "k", "syscheck_version": "1.0"},
            "environment": {
                "storage": [],
                "kernel_count": [],
                "failed_units": [],
                "boot_time": [],
            },
            "observations": [],
            "findings": [],
            "restrictions": [],
            "execution": {
                "commands_count": 0,
                "raw_diagnostics_count": 0,
                "observations_count": 0,
                "findings_count": 0,
            },
        }
        migrated = SnapshotMigrator.migrate(v1_data)
        assert migrated["schema_version"] == 3
        assert "recommendations" in migrated
        assert migrated["recommendations"] == []

        with tempfile.NamedTemporaryFile(mode="w", suffix=".json", delete=False) as f:
            path = f.name
            json.dump(migrated, f)
        try:
            loaded = SystemSnapshot.from_json(path)
            assert loaded.schema_version == 3
            assert loaded.recommendations == ()
        finally:
            os.unlink(path)


