class TestSnapshotV2Migration:
    """Schema v1 → v2 migration and v2 round-trip with recommendations."""

    def test_v3_roundtrip_with_recommendations(self, tmp_path):
        rec = DiagnosticRecommendation(
            recommendation_id="REC-F1",
            priority=2,
            title="Test",
            rationale="reason",
            source_finding_ids=("F1",),
            impact="medium",
            risk="low",
            effort="low",
            action_type="investigate",
        )
        snap = SystemSnapshot(
            metadata=SnapshotMetadata(hostname="h", kernel="k", syscheck_version="2.2"),
            findings=(
                FindingSnapshot(finding_id="F1", severity="P2", confidence="Certain"),
            ),
            recommendations=(rec,),
        )
        path = tmp_path / "snapshot.json"
        snap.to_json(path)
        loaded = SystemSnapshot.from_json(path)
        assert loaded.schema_version == 3
        assert len(loaded.recommendations) == 1
        assert loaded.recommendations[0].recommendation_id == "REC-F1"

    def test_v1_migrated_to_v3_has_empty_recommendations(self):
        import json
        import tempfile
        import os

        v1 = {
            "schema_version": 1,
            "metadata": {"hostname": "h", "kernel": "k", "syscheck_version": "1.0"},
            "environment": {
                "storage": [],
                "kernel_count": [],
                "failed_units": [],
                "boot_time": [],
            },
            "observations": [],
            "findings": [],
            "restrictions": [],
            "execution": {
                "commands_count": 0,
                "raw_diagnostics_count": 0,
                "observations_count": 0,
                "findings_count": 0,
            },
        }
        migrated = SnapshotMigrator.migrate(v1)
        with tempfile.NamedTemporaryFile(mode="w", suffix=".json", delete=False) as f:
            path = f.name
            json.dump(migrated, f)
        try:
            snap = SystemSnapshot.from_json(path)
            assert snap.schema_version == 3
            assert snap.recommendations == ()
        finally:
            os.unlink(path)

    def test_comparison_ignores_recommendations(self):
        """Snapshot comparison does not treat recommendation changes as regressions."""
        rec_old = DiagnosticRecommendation(
            recommendation_id="REC-F1", priority=2, title="t", rationale="r"
        )
        rec_new = DiagnosticRecommendation(
            recommendation_id="REC-F1", priority=1, title="t", rationale="r"
        )
        old = SystemSnapshot(
            metadata=SnapshotMetadata(hostname="h", kernel="k", syscheck_version="2"),
            recommendations=(rec_old,),
        )
        new = SystemSnapshot(
            metadata=SnapshotMetadata(hostname="h", kernel="k", syscheck_version="2"),
            recommendations=(rec_new,),
        )
        comp = SnapshotComparator.compare(old, new)
        # Comparison should not report recommendation priority change as a problem
        assert len(comp.new_findings) == 0
        assert len(comp.changed_findings) == 0


