class TestMixedRuleEngine:
    """Engine handles both migrated KernelCountRule and legacy rules."""

    def test_engine_returns_diagnostic_evaluation(self):
        engine = build_default_rule_engine()
        obs = Observation(
            obs_id="KRNL-INFO-001", category="kernel_count", details={"count": 4}
        )
        result = engine.evaluate([obs])
        assert isinstance(result, DiagnosticEvaluation)
        assert len(result.findings) == 1
        assert len(result.evidence) == 1
        assert result.evidence[0].evidence_id.startswith("EVIDENCE-KRNL-INFO-001")

    def test_engine_deterministic(self):
        engine = build_default_rule_engine()
        obs = Observation(
            obs_id="KRNL-INFO-001", category="kernel_count", details={"count": 4}
        )
        r1 = engine.evaluate([obs])
        r2 = engine.evaluate([obs])
        assert [f.finding_id for f in r1.findings] == [
            f.finding_id for f in r2.findings
        ]

    def test_legacy_rules_still_work(self):
        """Legacy rules (all except KernelCount) still return findings."""
        engine = build_default_rule_engine()
        obs = Observation(obs_id="BTRFS-SCRUB-001", category="btrfs_scrub")
        result = engine.evaluate([obs])
        assert len(result.findings) == 1
        assert result.findings[0].finding_id == "BTRFS-SCRUB-001"


