class TestMixedEngineWithStorage:
    """Engine handles KernelCount + Storage native results."""

    def test_both_native_results_present(self):
        engine = build_default_rule_engine()
        obs_list = [
            Observation(
                obs_id="KRNL-INFO-001", category="kernel_count", details={"count": 4}
            ),
            Observation(
                obs_id="STORAGE-USAGE-WARNING",
                category="storage_usage",
                details={
                    "mountpoint": "/",
                    "usage_percent": 81,
                    "threshold_state": "warning",
                },
            ),
        ]
        result = engine.evaluate(obs_list)
        fids = {f.finding_id for f in result.findings}
        assert "KRNL-INFO-001" in fids
        assert "STORAGE-USAGE-WARNING" in fids
        assert len(result.evidence) == 2

    def test_legacy_still_works_with_native_rules(self):
        engine = build_default_rule_engine()
        obs_list = [
            Observation(obs_id="BTRFS-SCRUB-001", category="btrfs_scrub"),
            Observation(
                obs_id="STORAGE-USAGE-WARNING",
                category="storage_usage",
                details={
                    "mountpoint": "/",
                    "usage_percent": 81,
                    "threshold_state": "warning",
                },
            ),
        ]
        result = engine.evaluate(obs_list)
        assert len(result.findings) == 2
        # Storage has evidence, legacy btrfs does not
        fids = {f.finding_id for f in result.findings}
        assert "BTRFS-SCRUB-001" in fids
        assert "STORAGE-USAGE-WARNING" in fids


