class TestWirePlumberSegfaultRuleEvidence:
    """WirePlumberSegfaultRule returns DiagnosticRuleResult with JOURNAL_EVENT."""

    def test_unsupported_category_empty(self):
        """Non-matching category returns empty result."""
        eb = EvidenceBuilder()
        rule = WirePlumberSegfaultRule(eb)
        obs = Observation(obs_id="x", category="segfault_minor")
        policy = FindingClassificationPolicy()
        result = rule.evaluate(obs, policy.classify(obs))
        assert result.finding is None
        assert len(result.evidence) == 0

    def test_general_subtype_empty(self):
        """General segfault type returns empty result for WirePlumber rule."""
        eb = EvidenceBuilder()
        rule = WirePlumberSegfaultRule(eb)
        obs = Observation(
            obs_id="SEGFAULT-SYS-001",
            category="segfault",
            details={"segfault_type": "system_wide"},
        )
        policy = FindingClassificationPolicy()
        result = rule.evaluate(obs, policy.classify(obs))
        assert result.finding is None
        assert len(result.evidence) == 0

    def test_wireplumber_subtype_returns_native_result(self):
        """WirePlumber subtype produces DiagnosticRuleResult with Finding and Evidence."""
        eb = EvidenceBuilder()
