        obs = Observation(
            obs_id="SEGFAULT-WP-001",
            category="segfault",
            details={
                "segfault_type": "wireplumber",
                "process": "wireplumber",
                "library": "libspa-libcamera.so",
                "count": 5,
                "unique_signatures": ("a", "b", "c", "d", "e"),
            },
        )
        policy = FindingClassificationPolicy()
        result = rule.evaluate(obs, policy.classify(obs))
        assert isinstance(result, DiagnosticRuleResult)
        assert result.finding is not None
