    def test_finding_id_unchanged(self):
        """Finding ID remains SEGFAULT-WP-001."""
        eb = EvidenceBuilder()
        rule = WirePlumberSegfaultRule(eb)
        obs = Observation(
            obs_id="SEGFAULT-WP-001",
            category="segfault",
            details={"segfault_type": "wireplumber"},
        )
        policy = FindingClassificationPolicy()
        result = rule.evaluate(obs, policy.classify(obs))
