    def test_severity_p2(self):
        """Severity remains P2."""
        eb = EvidenceBuilder()
        rule = WirePlumberSegfaultRule(eb)
        obs = Observation(
            obs_id="SEGFAULT-WP-001",
            category="segfault",
            details={"segfault_type": "wireplumber", "count": 5},
        )
        policy = FindingClassificationPolicy()
        result = rule.evaluate(obs, policy.classify(obs))
        assert result.finding.severity == "P2"

    def test_classification_audio(self):
        """Classification is AUDIO/SEGFAULT/ACTIONABLE/INVESTIGATE."""
        eb = EvidenceBuilder()
        rule = WirePlumberSegfaultRule(eb)
        obs = Observation(
            obs_id="SEGFAULT-WP-001",
            category="segfault",
            details={"segfault_type": "wireplumber"},
        )
        policy = FindingClassificationPolicy()
        classification = policy.classify(obs)
        result = rule.evaluate(obs, classification)
        assert result.finding.domain == DiagnosticDomain.AUDIO
        assert result.finding.kind == FindingKind.SEGFAULT
        assert result.finding.actionability == Actionability.ACTIONABLE
        assert result.finding.recommendation_intent == RecommendationIntent.INVESTIGATE

    def test_evidence_is_journal_event(self):
        """Evidence type is JOURNAL_EVENT."""
        eb = EvidenceBuilder()
        rule = WirePlumberSegfaultRule(eb)
        obs = Observation(
            obs_id="SEGFAULT-WP-001",
            category="segfault",
            details={"segfault_type": "wireplumber"},
        )
        policy = FindingClassificationPolicy()
        result = rule.evaluate(obs, policy.classify(obs))
        assert result.evidence[0].evidence_type == EvidenceType.JOURNAL_EVENT

    def test_evidence_contains_factual_data(self):
        """Evidence data preserves process, library, count without diagnosis."""
        eb = EvidenceBuilder()
        rule = WirePlumberSegfaultRule(eb)
        obs = Observation(
            obs_id="SEGFAULT-WP-001",
            category="segfault",
            details={
                "segfault_type": "wireplumber",
                "process": "wireplumber",
                "library": "libspa-libcamera.so",
                "count": 5,
            },
        )
        policy = FindingClassificationPolicy()
