    def test_deterministic(self):
        """Multiple evaluations produce identical results."""
        eb = EvidenceBuilder()
        rule = WirePlumberSegfaultRule(eb)
        obs = Observation(
            obs_id="SEGFAULT-WP-001",
            category="segfault",
            details={"segfault_type": "wireplumber", "count": 5},
        )
