class TestKernelTaintEngineIntegration:
    """SysCheckEngine._interpret() stores kernel taint Evidence."""

    def test_interpret_stores_kernel_taint_evidence(self):
        """Kernel taint Evidence is stored in engine.evidence_objects."""
        engine = SysCheckEngine(output_dir="/tmp/test_taint_evidence")
        engine.observations = [
            Observation(obs_id="KERNEL-TAINT-001", category="tainted"),
        ]
        engine._interpret()
        assert len(engine.evidence_objects) > 0
        assert engine.evidence_objects[0].evidence_type == EvidenceType.SYSTEM_STATE

    def test_interpret_with_mixed_runtime(self):
        """Kernel taint Evidence co-exists with other Evidence."""
        engine = SysCheckEngine(output_dir="/tmp/test_taint_evidence")
        engine.observations = [
            Observation(obs_id="KERNEL-TAINT-001", category="tainted"),
            Observation(obs_id="BTRFS-ERR-001", category="btrfs_error"),
            Observation(obs_id="BOOT-SLOW-001", category="boot_time"),
        ]
        engine._interpret()
        etypes = {ev.evidence_type for ev in engine.evidence_objects}
        assert EvidenceType.SYSTEM_STATE in etypes
        assert EvidenceType.FILESYSTEM_STATE in etypes
        assert EvidenceType.BOOT_MEASUREMENT in etypes
        # All three native rules produce Evidence
        assert len(engine.evidence_objects) == 3  # taint + btrfs + boot


