class TestCompleteNativeRuntime:
    """All eleven default rules are native; no rule returns bare Finding."""

    def test_all_rules_return_diagnostic_rule_result(self):
        """Every default registry rule produces DiagnosticRuleResult on its producing path."""
        engine = build_default_rule_engine()
        obs_list = [
            Observation(
                obs_id="KRNL-INFO-001", category="kernel_count", details={"count": 4}
            ),
            Observation(
                obs_id="STORAGE-USAGE-WARNING",
                category="storage_usage",
                details={
                    "mountpoint": "/",
                    "usage_percent": 81,
                    "threshold_state": "warning",
                },
            ),
            Observation(
                obs_id="SYSD-SYS-FAIL-001",
                category="systemd_failed",
                details={"scope": "system", "units": ["a.service"]},
            ),
            Observation(
                obs_id="SYSD-USR-FAIL-001",
                category="systemd_failed",
                details={"scope": "user", "units": ["b.service"]},
            ),
            Observation(obs_id="BTRFS-SCRUB-001", category="btrfs_scrub"),
            Observation(obs_id="BTRFS-ERR-001", category="btrfs_error"),
            Observation(
                obs_id="SEGFAULT-WP-001",
                category="segfault",
                details={"segfault_type": "wireplumber", "count": 5},
            ),
            Observation(
                obs_id="SEGFAULT-SYS-001",
                category="segfault",
                details={"segfault_type": "system_wide", "count": 8},
            ),
            Observation(
                obs_id="SEGFAULT-MIN-001",
                category="segfault_minor",
                details={"count": 2},
            ),
            Observation(obs_id="KERNEL-TAINT-001", category="tainted"),
            Observation(obs_id="BOOT-SLOW-001", category="boot_time"),
        ]
        result = engine.evaluate(obs_list)
        # Each native rule produce findings
        assert len(result.findings) == 11
        assert len(result.evidence) == 11
        # All findings have evidence_ids
        for f in result.findings:
            assert len(f.evidence_ids) > 0, (
                f"Finding {f.finding_id} has no evidence_ids"
            )
        # All evidence_ids resolve
        all_eids = {ev.evidence_id for ev in result.evidence}
        for f in result.findings:
            for eid in f.evidence_ids:
                assert eid in all_eids, (
                    f"Finding {f.finding_id} references unknown evidence {eid}"
                )
        # No duplicate evidence IDs
        assert len(all_eids) == 11
        # No duplicate finding IDs
        fids = [f.finding_id for f in result.findings]
        assert len(fids) == len(set(fids))

    def test_no_bare_finding_returned(self):
        """No default rule returns a bare Finding (all return DiagnosticRuleResult)."""
        engine = build_default_rule_engine()
        obs_list = [
            Observation(
                obs_id="KRNL-INFO-001", category="kernel_count", details={"count": 4}
            ),
            Observation(obs_id="BOOT-SLOW-001", category="boot_time"),
        ]
        result = engine.evaluate(obs_list)
        for f in result.findings:
            # Native findings always have evidence_ids
            assert len(f.evidence_ids) > 0
        # engine.evaluate() never went through _normalize bare-Finding path
        # because all rules return DiagnosticRuleResult

    def test_obs_to_finding_removed(self):
        """_obs_to_finding() has been completely removed (no runtime compatibility)."""
        # _obs_to_finding was removed in Iteration 21.
        # The rule engine alone produces all native results.
        assert not hasattr(SysCheckEngine, "_obs_to_finding"), (
            "_obs_to_finding should have been removed"
        )
        engine = build_default_rule_engine()
        obs_list = [
            Observation(
                obs_id="BOOT-SLOW-001",
                category="boot_time",
                details={"userspace_time": 31.2},
            ),
        ]
        result = engine.evaluate(obs_list)
        assert len(result.findings) == 1
        assert len(result.evidence) == 1
        assert result.findings[0].finding_id == "BOOT-SLOW-001"
        assert result.evidence[0].evidence_type == EvidenceType.BOOT_MEASUREMENT

    def test_normalize_contract(self):
        """_normalize() accepts only DiagnosticRuleResult."""
        from syscheck import DiagnosticRuleResult

        # _normalize is a staticmethod on DiagnosticRuleEngine
        engine = build_default_rule_engine()
        normalize = type(engine)._normalize
        # Empty DiagnosticRuleResult should return None
        empty = DiagnosticRuleResult()
        assert normalize(empty) is None
        # Result with finding should pass through
        from syscheck import Finding

        valid = DiagnosticRuleResult(
            finding=Finding(
                finding_id="TEST",
                title="Test",
                severity="P3",
                confidence="Certain",
            )
        )
        result = normalize(valid)
        assert isinstance(result, DiagnosticRuleResult)
        assert result.finding is not None
        assert result.finding.finding_id == "TEST"
        # Bare Finding is no longer accepted
        bare = Finding(
            finding_id="LEGACY",
            title="Legacy test",
            severity="P3",
            confidence="Certain",
        )
        with pytest.raises(Exception):
            normalize(bare)


class TestBootTimeCollector:
    """Boot-time collector payload completion (Iteration 23)."""

    @staticmethod
    def _cmd_ok(stdout: str) -> CmdResult:
        return CmdResult(
            command="",
            stdout=stdout,
            stderr="",
            return_code=0,
            execution_status="ok",
        )

    def _collect_with_mock(self, engine, **cmd_overrides):
        """Run collect_systemd with mocked _parallel_cmd returning controlled results."""
        from unittest.mock import patch

        results = {
            "sys_failed": self._cmd_ok(""),
            "usr_failed": self._cmd_ok(""),
            "analyze": self._cmd_ok(""),
            "blame": self._cmd_ok(""),
            "critical": self._cmd_ok(""),
            "timers": self._cmd_ok(""),
            "usr_timers": self._cmd_ok(""),
            "auto_restart": self._cmd_ok(""),
            "restarting": self._cmd_ok(""),
        }
        results.update(cmd_overrides)
        with patch.object(SysCheckEngine, "_parallel_cmd", return_value=results):
            engine.collect_systemd()

    def test_slow_boot_creates_raw_diagnostic(self):
        """Userspace > 30s produces boot_time RawDiagnostic with timing facts."""
        engine = SysCheckEngine(output_dir="/tmp/test_boot_collector")
        analyze = (
            "Startup finished in 14.425s (firmware) + 8.130s (loader) + "
            "2.906s (kernel) + 5.034s (initrd) + 31.2s (userspace) = 61.695s\n"
            "graphical.target reached after 31.2s in userspace."
        )
        blame = "8.708s man-db.service\n5.553s graphical.target"
        critical = (
            "graphical.target @5.553s\n"
            "\u2514\u2500multi-user.target @5.553s\n"
            "  \u2514\u2500libvirtd.service @5.055s"
        )
        self._collect_with_mock(
            engine,
            analyze=self._cmd_ok(analyze),
            blame=self._cmd_ok(blame),
            critical=self._cmd_ok(critical),
        )

        boot_raws = [r for r in engine.raw_diagnostics if r.category == "boot_time"]
        assert len(boot_raws) == 1
        raw = boot_raws[0]
        assert raw.source_id == "BOOT-SLOW-001"
        assert raw.payload["userspace_time"] == 31.2
        assert raw.payload["threshold"] == 30.0
        assert "root_cause" not in raw.payload
        assert "recommended_action" not in raw.payload
        assert "disk_is_slow" not in raw.payload

    def test_normal_boot_no_raw_diagnostic(self):
        """Userspace <= 30s produces no boot_time RawDiagnostic."""
