    def test_boundary_thirty_seconds(self):
        """30.0s produces no RawDiagnostic; 30.1s produces one."""
        template = (
            "Startup finished in 0.000s (firmware) + 0.000s (loader) + "
            "0.000s (kernel) + 0.000s (initrd) + {t}s (userspace) = {t}s\n"
            "graphical.target reached after {t}s in userspace."
        )
        blame = "1.0s graphical.target"
        critical = "graphical.target @1.0s"

        # Exactly 30.0 — no RawDiagnostic
        engine_30 = SysCheckEngine(output_dir="/tmp/test_boot_collector")
        self._collect_with_mock(
            engine_30,
            analyze=self._cmd_ok(template.format(t="30.0")),
            blame=self._cmd_ok(blame),
            critical=self._cmd_ok(critical),
        )
        boot_30 = [r for r in engine_30.raw_diagnostics if r.category == "boot_time"]
        assert len(boot_30) == 0, "30.0s should not produce a RawDiagnostic"

        # 30.1 — RawDiagnostic produced
        engine_31 = SysCheckEngine(output_dir="/tmp/test_boot_collector")
        self._collect_with_mock(
            engine_31,
            analyze=self._cmd_ok(template.format(t="30.1")),
            blame=self._cmd_ok(blame),
            critical=self._cmd_ok(critical),
        )
        boot_31 = [r for r in engine_31.raw_diagnostics if r.category == "boot_time"]
        assert len(boot_31) == 1, "30.1s should produce a RawDiagnostic"
        assert boot_31[0].payload["userspace_time"] == 30.1

