        self._collect_with_mock(
            engine,
            gpu_nvidia_xid_79=self._cmd_ok(self._make_xid79_line(prefix="nvidia")),
        )
        raws = [
            r for r in engine.raw_diagnostics if r.source_id == "GPU-NVIDIA-XID-79-001"
        ]
        assert len(raws) == 1

